package local.velo.bridge;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
public class ClearUiTest extends Instrumentation {
 int count;MainActivity app;Context c;void check(boolean b,String label)throws Exception{count++;if(!b)throw new Exception(label);}void main(Runnable r){runOnMainSync(r);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String value){if(n==null)return null;if(n.getText()!=null&&n.getText().toString().equals(value))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo p=find(n.getChild(i),value);if(p!=null)return p;}return null;}
 void click(String text)throws Exception{AccessibilityNodeInfo node=null;for(int attempt=0;attempt<20&&node==null;attempt++){node=find(getUiAutomation().getRootInActiveWindow(),text);if(node==null)Thread.sleep(150);}check(node!=null,"find "+text);android.graphics.Rect b=new android.graphics.Rect();node.getBoundsInScreen(b);long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,b.centerX(),b.centerY(),0));sendPointerSync(MotionEvent.obtain(t,t+70,MotionEvent.ACTION_UP,b.centerX(),b.centerY(),0));Thread.sleep(300);}
 void touch(int action,int count,float span,long down)throws Exception{MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=app.preview.getWidth()/2f+(i==0?-span:span);coords[i].y=app.dp(250);coords[i].pressure=1;coords[i].size=1;}MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,props,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);main(()->app.preview.dispatchTouchEvent(event));event.recycle();Thread.sleep(30);}
 void pinch()throws Exception{long down=SystemClock.uptimeMillis();touch(MotionEvent.ACTION_DOWN,1,app.dp(60),down);touch(MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),2,app.dp(60),down);for(int i=1;i<=12;i++)touch(MotionEvent.ACTION_MOVE,2,app.dp(60+i*7),down);double x=app.preview.centerX,y=app.preview.centerY;touch(MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),2,app.dp(144),down);touch(MotionEvent.ACTION_UP,1,app.dp(144),down);check(Math.abs(x-app.preview.centerX)<1e-9&&Math.abs(y-app.preview.centerY)<1e-9,"pinch release does not fling map");}
 void dragSheet(MapSheet sheet,float delta)throws Exception{int[] pos=new int[2];main(()->sheet.getLocationOnScreen(pos));float x=pos[0]+sheet.getWidth()/2f,y=pos[1]+15*sheet.density;long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0));for(int i=1;i<=12;i++){Thread.sleep(18);sendPointerSync(MotionEvent.obtain(t,SystemClock.uptimeMillis(),MotionEvent.ACTION_MOVE,x,y+delta*i/12,0));}sendPointerSync(MotionEvent.obtain(t,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y+delta,0));Thread.sleep(500);}
 String read(InputStream in)throws Exception{try(InputStream s=in){return new String(NearbyRoads.read(s,4*1024*1024),"UTF-8");}}
 void shot(String name)throws Exception{Thread.sleep(700);Bitmap image=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 String js(String script)throws Exception{java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> v=new java.util.concurrent.atomic.AtomicReference<>();main(()->app.preview.engine.web.evaluateJavascript(script,s->{v.set(s);latch.countDown();}));if(!latch.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new Exception("Web renderer timeout");return new JSONArray("["+v.get()+"]").getString(0);}
 public void onStart(){Bundle out=new Bundle();c=getTargetContext();try{getUiAutomation();c.stopService(new Intent(c,RideService.class));c.stopService(new Intent(c,DeviceLinkService.class));c.getSharedPreferences("navigation",0).edit().remove("device_address").commit();app=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(500);AppStore db=AppStore.get(c);int favorites=db.favorites(false).size();RouteModel model=BikePlanner.parse(read(getContext().getAssets().open("route.json")),"清除验收路线");String saved=db.saveRoute("clear-acceptance","保留路线",model);main(()->{try{RouteStore.saveActive(c,model);}catch(Exception e){throw new RuntimeException(e);}app.origin=new MainActivity.Place("起点",33.55,133.50);app.destination=new MainActivity.Place("终点",33.56,133.51);app.via.add(new MainActivity.Place("途经",33.555,133.505));app.persistDraft();app.draftChanged=false;app.mode="plan";app.showTab("map");});Thread.sleep(700);click("清除路线");click("取消");check(RouteStore.route==model&&app.destination!=null,"cancel retains route and draft");click("清除路线");click("清除");Thread.sleep(500);check(RouteStore.route==null&&!RouteStore.replay,"clear removes active route");check(app.origin==null&&app.destination==null&&app.via.isEmpty(),"clear removes all draft points");check(!app.draftChanged&&!app.preview.pending&&app.preview.from==null&&app.preview.to==null&&app.preview.via.isEmpty(),"map contains no old route markers");check(!app.preview.replayRunning&&app.preview.replayRoute==null,"playback cleared");check(db.favorites(false).size()==favorites&&db.route(saved)!=null,"favorites and route library preserved");check(c.getSharedPreferences("navigation",0).getString("last_source","").equals("none"),"clear persisted");RouteStore.initialized=false;RouteStore.load(c);check(RouteStore.route==null,"cold load cannot resurrect old route cache");check(app.mode.equals("home")&&app.contentHost.getVisibility()==View.GONE,"clear returns to map home");main(()->app.showTab("favorites"));Thread.sleep(400);check(app.contentHost.getAlpha()==1&&app.contentHost.getTranslationY()==0,"page transition finishes in stable position");shot("velo-v104-favorites.png");main(()->{app.mode="home";app.showTab("map");app.preview.center(33.551833,133.507556,16);});Thread.sleep(2500);shot("velo-v104-home.png");main(()->{try{RouteStore.saveActive(c,model);}catch(Exception e){throw new RuntimeException(e);}app.draftChanged=false;app.startRide("PHONE");});Thread.sleep(1800);check(RideService.running,"ride started for end-and-clear flow");main(()->app.requestClearRoute());click("清除");Thread.sleep(700);check(!RideService.running&&RouteStore.route==null,"active ride ends before clearing route");check(db.rides().stream().anyMatch(r->!r.optBoolean("active")),"ended ride record retained");main(()->{app.planning=true;app.generation=100;app.clearRouteNow();});check(!app.planning&&app.generation>100,"clear invalidates pending planning result");out.putString("checks",count+" route clear, persistence, cancel, ride end and UI transition checks passed");finish(Activity.RESULT_OK,out);}catch(Throwable e){try{shot("clear-failed.png");}catch(Exception ignored){}out.putString("error",count+": "+e.toString());finish(Activity.RESULT_CANCELED,out);}}
}
